param([Parameter(Mandatory)][string]$CandidateSnapshotId,[Parameter(Mandatory)][string]$ExperimentId)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
function Require([bool]$Condition,[string]$Message){if(!$Condition){throw $Message}};function BytesHash([byte[]]$Bytes){[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($Bytes))};function RangeHash([byte[]]$Bytes,[int]$Offset,[int]$Count){$stream=[IO.MemoryStream]::new($Bytes,$Offset,$Count,$false);try{[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($stream))}finally{$stream.Dispose()}}
$repositoryRoot=(& git -C $PSScriptRoot rev-parse --show-toplevel).Trim();$candidateRoot=Join-Path $repositoryRoot "artifacts/performance/$CandidateSnapshotId";$experimentRoot=Join-Path $candidateRoot $ExperimentId;$measurementPath=Join-Path $experimentRoot 'measurements.csv';$strictPath=Join-Path $candidateRoot 'validation/display-provider-strict-verification.json';$receiptPath=Join-Path $experimentRoot 'ledger-append.json';$ledgerPath=Join-Path $repositoryRoot 'docs/performance/OPTIMIZATION_MEASUREMENTS.csv';Require(!(Test-Path $receiptPath))'Receipt exists.';$strict=Get-Content -Raw $strictPath|ConvertFrom-Json -DateKind String;Require($strict.Accepted -and $strict.Rows-eq 210)'Strict acceptance differs.';$manifest=@(Import-Csv (Join-Path $candidateRoot 'manifest.csv'));$appender=@($manifest|Where-Object Path -CEQ 'scripts/performance/Append-DisplayProviderSnapshotMeasurements.ps1');Require($appender.Count-eq 1 -and $appender[0].SHA256-ceq(Get-FileHash -Algorithm SHA256 $PSCommandPath).Hash)'Appender differs.';$bytes=[IO.File]::ReadAllBytes($measurementPath);Require((BytesHash $bytes)-ceq $strict.MeasurementsSHA256)'Measurements changed.';$encoding=[Text.UTF8Encoding]::new($false,$true);$text=$encoding.GetString($bytes).TrimStart([char]0xFEFF);$rows=@($text|ConvertFrom-Csv);Require($rows.Count-eq 210 -and @($rows|Where-Object{$_.experiment_id-cne $ExperimentId -or $_.perf_id-cne 'PERF-022'}).Count-eq 0)'Rows differ.';$headerEnd=[Array]::IndexOf($bytes,[byte]10);$suffix=[byte[]]$bytes[($headerEnd+1)..($bytes.Length-1)];Require($bytes[-1]-eq 10 -and @($suffix|Where-Object{$_-eq 10}).Count-eq 210)'Suffix differs.'
$expectedLength=41628950L;$expectedHash='EBB7BCCDB977FDA9D8DEBD5B7D353FD3025D0A45218733D839F8818ABA14C038';$expectedLines=41116;$expectedRows=41115;$stream=[IO.File]::Open($ledgerPath,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);try{Require($stream.Length-eq $expectedLength)'Ledger length differs.';$prefix=[byte[]]::new([int]$expectedLength);$stream.ReadExactly($prefix,0,$prefix.Length);Require((BytesHash $prefix)-ceq $expectedHash -and $prefix[-1]-eq 10)'Prefix differs.';$prefixText=$encoding.GetString($prefix).TrimStart([char]0xFEFF);Require($prefixText.Split([char]10).Length-1-eq $expectedLines -and !$prefixText.Contains('"'+$ExperimentId+'"'))'Prefix rows differ.';Require($prefixText.Substring(0,$prefixText.IndexOf([char]10)).TrimEnd([char]13)-ceq $text.Substring(0,$text.IndexOf([char]10)).TrimEnd([char]13))'Schema differs.';$stream.Write($suffix,0,$suffix.Length);$stream.Flush($true);$newLength=$stream.Length;$stream.Position=0;$newBytes=[byte[]]::new([int]$newLength);$stream.ReadExactly($newBytes,0,$newBytes.Length);$newHash=BytesHash $newBytes;Require((RangeHash $newBytes 0 $prefix.Length)-ceq $expectedHash -and (RangeHash $newBytes $prefix.Length $suffix.Length)-ceq(BytesHash $suffix))'Readback differs.'}finally{$stream.Dispose()};$receipt=[ordered]@{Verdict='ACCEPT';CandidateSnapshotId=$CandidateSnapshotId;ExperimentId=$ExperimentId;PerfId='PERF-022';OldLength=$expectedLength;OldSHA256=$expectedHash;OldLines=$expectedLines;OldRows=$expectedRows;NewLength=$newLength;NewSHA256=$newHash;NewLines=$expectedLines+210;NewRows=$expectedRows+210;PrefixLength=$expectedLength;PrefixSHA256=$expectedHash;SuffixLength=$suffix.Length;SuffixSHA256=BytesHash $suffix;AppendedRows=210;MeasurementsSHA256=BytesHash $bytes;StrictReportSHA256=(Get-FileHash -Algorithm SHA256 $strictPath).Hash;AppenderSHA256=(Get-FileHash -Algorithm SHA256 $PSCommandPath).Hash};$json=$receipt|ConvertTo-Json -Depth 4;$file=[IO.File]::Open($receiptPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$write=$encoding.GetBytes($json+[Environment]::NewLine);$file.Write($write,0,$write.Length)}finally{$file.Dispose()};$json
